import React, { Component } from "react";
import * as THREE from "three";

var STLLoader = require("three-stl-loader")(THREE);
var OrbitControls = require("three-orbit-controls")(THREE);
class ThreeDViewer extends Component {
  componentDidMount() {
    var scene = new THREE.Scene();
    var camera = new THREE.PerspectiveCamera(
      10,
      window.innerWidth / window.innerHeight,
      0.1,
      100000
    );
    camera.position.x = 13000;
    var light = new THREE.AmbientLight(0xffffff, 1);
    scene.add(light);
    var light = new THREE.PointLight(0xffffff, 1, 100);
    light.position.set(50, 50, 50);
    scene.add(light);
    var light = new THREE.DirectionalLight(0xffffff, 0.5);
    scene.add(light);

    var canvas = document.querySelector("#editor");
    var renderer = new THREE.WebGLRenderer({ canvas });

    //var renderer = new THREE.WebGLRenderer();
    renderer.setSize(window.innerWidth, window.innerHeight);
    new OrbitControls(camera, renderer.domElement);
    //this.mount.appendChild(renderer.domElement);

    /*
    var geometry = new THREE.BoxGeometry(1, 1, 1);
    geometry.center();
    var material = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      metalness: 0.5,
      roughness: 0.5
    });*/

    ///////

    var length = 8,
      width = 8;

    var shape = new THREE.Shape();
    shape.moveTo(0, 0);
    shape.lineTo(0, width);
    shape.lineTo(length, width);
    shape.lineTo(length, 0);
    shape.lineTo(0, 0);

    var extrudeSettings = {
      amount: 22,
      bevelEnabled: false,
      bevelSegments: 2,
      steps: 2,
      bevelSize: 1,
      bevelThickness: 1
    };
    var geometry = new THREE.ExtrudeBufferGeometry(shape, extrudeSettings);
    geometry.center();
    var material = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      metalness: 0.5,
      roughness: 0.5
    });

    var mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    //var obj = new THREE.Mesh(geometry, material);
    //scene.add(obj);

    /*var loader = new STLLoader();
    loader.load("./box.stl", geometry => {
      geometry.center();
      var material = new THREE.MeshBasicMaterial({ color: 0x00ff00 });
      var mesh = new THREE.Mesh(geometry, material);
      scene.add(mesh);
    });*/

    var animate = function() {
      requestAnimationFrame(animate);
      renderer.render(scene, camera);
      var windowAspectRatio = window.innerHeight / window.innerWidth; //used to actively resize the canvas when it is changed in size
      var container = document.getElementById("container"); //used to actively resize the canvas when it is changed in size
      renderer.setSize(
        container.clientWidth,
        container.clientWidth * windowAspectRatio
      ); //used to actively resize the canvas when it is changed in size
    };
    animate();
  }
  render() {
    //return <div ref={ref => (this.mount = ref)} />;

    return (
      <div id="container">
        <canvas id="editor"></canvas>
      </div>
    );
  }
}
export default ThreeDViewer;
